from numpy import *

tn = array([int] * 1000)
tm = array([int] * 1000)

def Saisie():
    b = False
    while not b:
        n = int(input('Donner n: '))
        m = int(input('Donner m: '))
        b = 10 <= n < m <= 999
    return n, m

def Somme_div(n):
    S = 0
    d = 1
    while d < n:
        if n % d == 0:
            S += d
            d += 1
        else:
            d += 1
    return S

def Suite_aliquote(a, t):
    t[0] = a
    i = 1
    while a != 1:
        a = Somme_div(a)
        t[i] = a
        i += 1
    return i

def commun(tn, tm, j, k):
    S = 0
    for i in range(j):
        for loop in range(k):
            if (tn[i]) == tm[loop]:
                S += 1
    return S
